 const themeWords={Fantasia:['dragão','espada','magia','castelo','feitiço','elfo','orco','fênix','gelo','fada','chicote','poção','escudo'],Cyberpunk:['drone','laser','neon','robô','android','hacker','implante','arma','carro','cidade'],Terror:['fantasma','monstro','vampiro','zumbi','sombra','sino','sangue','demônio','corvo','lobisomem']};
 const iconFor=t=>{if(/drag[aã]o/.test(t))return'🐉';if(/chicote/.test(t))return'〰';if(/espada|arma|faca|lan[cç]a/.test(t))return'⚔';if(/fantasma|esp[ií]rito/.test(t))return'👻';if(/rob[oô]|drone|android/.test(t))return'🤖';if(/f[eé]nix|ave|p[aá]ssaro/.test(t))return'🕊';if(/cavalo|lobo|c[aã]o/.test(t))return'🐺';if(/castelo|torre|casa/.test(t))return'🏰';if(/flor|[aá]rvore|planta/.test(t))return'🌿';if(/portal/.test(t))return'🌀';if(/chuva|tempestade|raio/.test(t))return'🌩';if(/gelo|neve/.test(t))return'❄';if(/fogo|chama/.test(t))return'🔥';if(/rob[oô]|máquina/.test(t))return'⚙';return'✦'};
 function makeResponse(command,world,challenge){const card=document.createElement('article');card.className='response';const stamp=`D${String(1+Math.floor(turn/8)).padStart(2,'0')} · ${String(8+Math.floor((worldTime%720)/60)).padStart(2,'0')}:${String(worldTime%60).padStart(2,'0')}`;card.innerHTML=`<div class="response-top"><span>COMANDO ${String(turn).padStart(2,'0')}</span><span>${stamp}</span></div><div class="block"><strong>🖼️ ESCUTADO</strong>“${escapeHTML(command)}”</div><div class="block"><strong>🌍 MUNDO ALTERADO</strong>${escapeHTML(world)}</div><div class="block challenge"><strong>🎲 EVENTO / DESAFIO</strong>${escapeHTML(challenge)}</div>`;$('#feed').prepend(card);$('#welcome')?.classList.add('hidden');$('#turnCount').textContent=`${turn} ${turn===1?'EVENTO':'EVENTOS'}`;}
 function escapeHTML(s){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
