+function updateMetrics(){$('#sparkValue').text(String(sparks).padStart(2,'0'));$('#sparkBar').style.width=`${Math.min(100,8+sparks*8)}%`;$('#dangerValue').text(`${danger}%`);$('#dangerBar').style.width=`${danger}%`;$('#milestoneValue').text(milestones);$('#milestoneBar').style.width=`${Math.min(100,5+milestones*18)}%`;$('#inventoryCount').textContent=`${inventory.length} ${inventory.length===1?'ITEM':'ITENS'}`;$('#inventory').innerHTML=inventory.length?inventory.slice(-8).map(x=>`<span class="token">${escapeHTML(x)}</span>`).join(''):'<span class="empty-token">Suas descobertas aparecem aqui.</span>';drawScene()}

