$('#inventory').innerHTML=inventory.length?inventory.slice(-8).map(x=>`<span class="token">${escapeHTML(x)}</span>`).join(''):'<span class="empty-token">Suas descobertas aparecem aqui.</span>';drawScene()}
const pick=(arr)=>arr[Math.floor(rand()*arr.length)];
function processCommand(raw){const command=raw.trim();if(!command)return;turn++;worldTime=(worldTime+7+command.length%13)%720;const low=command.toLocaleLowerCase('pt-BR');let world='',challenge='',weatherChanged=false;
const creates=/(aparece|surge|cria|crie|invoca|invoco|conjura|materializa|nasce|desenha|constr[oó]i|ergue|abre|surja|traga|chama|solta|lan[cç]a)/i.test(low);
const takes=/(peguei|pego|pegar|pega|equip[oa]|seguro|visto|uso|usar|coloca|coloco|carrego|adiciona|quero|preciso)/i.test(low);
const weatherMatch=/(chuva|chove|tempestade|neve|nevar|sol|nublado|n[eé]voa|neblina|vento|raio|rel[aâ]mpago)/i.test(low);
const changeMatch=/(muda|transforma|vira|agora|fica|torna|converte)/i.test(low);
const hostile=/(ataca|ataque|matar|mata|destr[oó]i|explod|invade|armadilha|perigo|sangue|guerra)/i.test(low);
const friendly=/(ajuda|amigo|aliad|protege|cura|salva|paz|abra[cç]a|resgata)/i.test(low);
const key=Object.keys(themes).find(k=>low.includes(k.toLocaleLowerCase('pt-BR')));if(key&&key!==theme){theme=key;$('#worldTitle').textContent=themes[theme].title;$('#sceneName').textContent=themes[theme].title.toLocaleUpperCase('pt-BR');$('#themeBadge').textContent=`${theme==='Fantasia'?'✧':theme==='Cyberpunk'?'⌁':theme==='Terror'?'◒':'✦'} ${theme.toLocaleUpperCase('pt-BR')}`;$('#weather').textContent=themes[theme].weather;world=`O mundo se dobra para ${theme}: ${themes[theme].caption} O horizonte inteiro troca de pele.`}
if(weatherMatch){const weather=/(chuva|chove|tempestade|neve|nevar|sol|nublado|vento|raio|rel[aâ]mpago)/i.test(low)?pick(['☂ CHUVA FORTE','ϟ TEMPESTADE ELÉTRICA','❄ NEVE DANÇANTE','☼ CÉU ABERTO','〰 VENTO CORTANTE']):'☁ NÉVOA ESPESSA';$('#weather').textContent=weather;world=world||`O ar muda de repente: ${weather.toLocaleLowerCase('pt-BR')} cobre o vale, e cada superfície brilha sob a nova luz.`}
const noun=command.replace(/^(por favor[, ]*)?(ent[aã]o[, ]*)?/i,'').replace(/\b(aparece|surge|cria|crie|invoca|invoco|conjura|materializa|nasce|desenha|constr[oó]i|ergue|abre|surja|traga|chama|solta|lan[cç]a|peguei|pego|pegar|pega|equip[oa]|seguro|visto|uso|usar|coloca|coloco|carrego|adiciona|quero|preciso|um|uma|uns|umas|o|a|os|as|na|no|da|do|de|em|minha|minhas|meu|meus|para|por|com|no|na)\b/ig,'').replace(/[.!?]+$/,'').trim();
const safeNoun=noun.slice(0,55)||'um fragmento da sua ideia';const icon=iconFor(low);
if(takes){const item=safeNoun.length>30?safeNoun.slice(0,30)+'…':safeNoun;inventory.push(`${icon} ${item}`);entities.push({icon,color:'#d8ff68'});world=world||`Um brilho percorre sua mochila: ${safeNoun} aparece em suas mãos, ainda morno de outro lugar.`;challenge=`A peça vibra como se reconhecesse você. ${pick(['Uma marca antiga acende na superfície.','O peso muda sozinho na sua palma.','Algo responde de dentro da mochila.'])} O que você faz com ela?`}
else if(weatherMatch){challenge=`O ambiente reage: ${pick(['uma figura encapuzada aponta para o céu alterado.','um animal escondido abandona o abrigo.','vozes distantes acompanham o novo ritmo da chuva.'])} Como você aproveita a mudança?`}
else if(/muda|transforma|vira|agora|fica|torna|converte/i.test(low)&&!key){entities.push({icon,color:'#9ae5c1'});world=world||`A realidade se remolda ao seu comando. ${safeNoun} pulsa em contornos novos, e o cenário inteiro parece prender a respiração.`;challenge=`O mundo aceita a transformação — mas alguma coisa ficou diferente demais. ${pick(['Um observador surge na encosta.','O chão se abre numa fenda luminosa.','Uma voz pergunta o preço da mudança.'])} Qual é seu próximo movimento?`}
else{entities.push({icon,color:'#d8ff68'});if(entities.length>9)entities.shift();world=world||`${creates?'Uma presença toma forma':'A sua frase ganha corpo'}: ${safeNoun}. Partículas acendem no ar e a paisagem abre espaço para a nova realidade.`;challenge=`${pick(['A guardiã do vale estreita os olhos.','Uma criatura próxima fareja o ar.','O chão vibra sob seus pés.','Uma voz ecoa das ruínas.','Um pequeno espírito salta para mais perto.'])} ${hostile?'A tensão aumenta — há olhos voltados para você.':friendly?'Sua presença inspira confiança.':'A novidade ainda não sabe se é amiga ou ameaça.'} O que você diz agora?`}
if(key&&!world.includes('se dobra'))world=`O cenário se ajusta a ${key} enquanto ${world.charAt(0).toLowerCase()+world.slice(1)}`;
if(hostile)danger=Math.min(96,danger+12);else if(friendly)danger=Math.max(3,danger-8);else danger=Math.min(90,danger+2);
sparks=Math.min(99,sparks+1+Math.floor(command.length/44));if(turn%3===0){milestones++;challenge=`MARCO ${milestones} DESBLOQUEADO — ${pick(['uma rota secreta aparece no mapa.','um fragmento de memória volta à tona.','uma nova presença acompanha seus passos.'])} ${challenge}`;danger=Math.max(3,danger-3)}
if(entities.length>10)entities.shift();$('#caption').textContent=world;$('#clock').textContent=`DIA ${String(1+Math.floor(turn/8)).padStart(2,'0')} · ${String(8+Math.floor(worldTime/60)).padStart(2,'0')}:${String(worldTime%60).padStart(2,'0')}`;$('#coords').textContent=`N ${String(4+turn*3).padStart(2,'0')}° · L ${String(18+turn*2).padStart(2,'0')}°`;$('#worldIndex').textContent=String(1+Math.floor(milestones/3)).padStart(2,'0');$('#turnCount').textContent=`${turn} ${turn===1?'EVENTO':'EVENTOS'}`;makeResponse(command,world,challenge);updateMetrics();$('#command').value='';$('#command').focus()}

