const themesList=[...document.querySelectorAll('.theme')];let chosen='Fantasia';themesList.forEach(b=>b.addEventListener('click',()=>{themesList.forEach(x=>x.classList.remove('selected'));b.classList.add('selected');chosen=b.dataset.theme;$('#begin').textContent=`ESCOLHER ${chosen.toLocaleUpperCase('pt-BR')} E COMEÇAR ↗`}));
$('#begin').addEventListener('click',()=>{theme=chosen;$('#worldTitle').textContent=themes[theme].title;$('#sceneName').textContent=themes[theme].title.toLocaleUpperCase('pt-BR');$('#themeBadge').textContent=`${theme==='Fantasia'?'✧':theme==='Cyberpunk'?'⌁':theme==='Terror'?'◒':'✦'} ${theme.toLocaleUpperCase('pt-BR')}`;$('#weather').textContent=themes[theme].weather;$('#caption').textContent=themes[theme].caption;$('#intro').classList.add('hidden');resize();$('#command').focus()});
$('#form').addEventListener('submit',e=>{e.preventDefault();processCommand($('#command').value)});
document.querySelectorAll('.suggestion').forEach(b=>b.addEventListener('click',()=>processCommand(b.textContent)));
function toast(msg){const n=document.createElement('div');n.className='toast';n.textContent=msg;document.body.appendChild(n);setTimeout(()=>n.remove(),2800)}
function toggleMic(){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){toast('Reconhecimento de voz indisponível neste navegador. Digite seu comando.');return}if(listening){recognition?.stop();return}recognition=new SR();recognition.lang='pt-BR';recognition.interimResults=true;recognition.continuous=false;listening=true;$('#mic').classList.add('listening');$('#voiceHint').textContent='OUVINDO… FALE SEU COMANDO';recognition.onresult=e=>{let interim='';for(let i=e.resultIndex;i<e.results.length;i++){const text=e.results[i][0].transcript;if(e.results[i].isFinal){$('#command').value=text;processCommand(text)}else interim=text}if(interim)$('#command').placeholder=`“${interim}”`};recognition.onerror=e=>{if(e.error!=='no-speech'&&e.error!=='aborted')toast('Não consegui acessar o microfone. Verifique a permissão do navegador.');finishMic()};recognition.onend=finishMic;try{recognition.start()}catch(e){finishMic();toast('Não foi possível iniciar o microfone.')}}
function finishMic(){listening=false;$('#mic').classList.remove('listening');$('#voiceHint').textContent='APERTE O MICROFONE PARA FALAR · OU DIGITE SUA IDEIA';$('#command').placeholder='Diga ou escreva o que acontece…'}$('#mic').addEventListener('click',toggleMic);
$('#reset').addEventListener('click',()=>{turn=0;sparks=0;danger=12;milestones=0;worldTime=0;entities=[];inventory=[];theme='Fantasia';chosen='Fantasia';$('#worldTitle').textContent=themes[theme].title;$('#sceneName').textContent=themes[theme].title.toLocaleUpperCase('pt-BR');$('#themeBadge').textContent='✧ FANTASIA';$('#weather').textContent=themes[theme].weather;$('#caption').textContent=themes[theme].caption;$('#clock').textContent='DIA 01 · 08:42';$('#worldIndex').textContent='01';$('#feed').innerHTML='<div class="welcome" id="welcome"><div class="welcome-mark">✳</div><h3>Sua história começa agora.</h3><p>Escolha um tema e fale ou escreva sua primeira ação. Crie algo, mude o clima, convoque um aliado — o mundo vai responder.</p></div>';$('#turnCount').textContent='0 EVENTOS';themesList.forEach(x=>x.classList.toggle('selected',x.dataset.theme==='Fantasia'));$('#begin').textContent='ESCOLHER FANTASIA E COMEÇAR ↗';$('#intro').classList.remove('hidden');updateMetrics()});
setInterval(()=>{if(!$('#intro').classList.contains('hidden'))return;worldTime=(worldTime+1)%720;const hour=8+Math.floor(worldTime/60),minute=worldTime%60;$('#clock').textContent=`DIA ${String(1+Math.floor(turn/8)).padStart(2,'0')} · ${String(hour).padStart(2,'0')}:${String(minute).padStart(2,'0')}`},1000);
resize();updateMetrics();
})();
</script></body></html>

